import os
import psycopg2
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'inventory')
DB_USER = os.environ.get('DB_USER', 'app_user')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def rate_limit_check(client_ip):
    """Basic in-memory rate limiting - not production grade"""
    current = time.time()
    window = getattr(rate_limit_check, '_window', {})
    hits = window.get(client_ip, [])
    hits = [t for t in hits if current - t < 60]
    hits.append(current)
    window[client_ip] = hits
    rate_limit_check._window = window
    return len(hits) <= 100

@app.route('/api/v2/products/search', methods=['GET'])
def search_products():
    client_ip = request.headers.get('X-Forwarded-For', request.remote_addr)
    if not rate_limit_check(client_ip):
        return jsonify({'error': 'rate limited'}), 429

    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    warehouse = request.args.get('warehouse', '')

    # Validate price params
    try:
        min_p = float(min_price)
        max_p = float(max_price)
    except ValueError:
        return jsonify({'error': 'invalid price range'}), 400

    # Build query with parameterized prices
    conditions = ["price BETWEEN %s AND %s"]
    params = [min_p, max_p]

    if category:
        # Category uses an enum check
        valid_categories = ['electronics', 'clothing', 'food', 'tools', 'furniture']
        if category not in valid_categories:
            return jsonify({'error': 'invalid category'}), 400
        conditions.append(f"category = '{category}'")

    if warehouse:
        # Warehouse filter - validated against known pattern
        if not warehouse.replace('-', '').replace('_', '').isalnum():
            return jsonify({'error': 'invalid warehouse id'}), 400
        conditions.append(f"warehouse_id = '{warehouse}'")

    # Aggregate filter - allows complex expressions for reporting
    having_expr = request.args.get('having', '')

    where_clause = ' AND '.join(conditions)

    query = f"SELECT product_id, name, price, stock_qty, warehouse_id FROM products WHERE {where_clause}"

    group_by = request.args.get('group', '')
    if group_by:
        allowed_groups = ['category', 'warehouse_id', 'supplier_id']
        if group_by in allowed_groups:
            query = f"SELECT {group_by}, COUNT(*), AVG(price), SUM(stock_qty) FROM products WHERE {where_clause} GROUP BY {group_by}"
            if having_expr:
                query += f" HAVING {having_expr}"

    query += " LIMIT 200"

    try:
        cur = get_db().cursor()
        cur.execute(query, params)
        rows = cur.fetchall()
        return jsonify({'results': [list(r) for r in rows], 'count': len(rows)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    cur = get_db().cursor()
    cur.execute("SELECT * FROM products WHERE product_id = %s", (product_id,))
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'product': list(row)})

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
